<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {WorkflowCommandError} from './workflow-operation'
import type {WorkflowDeliveryPreview,WorkflowDeliveryStatus,WorkflowDeliveryValidation,WorkflowOperationProvider,WorkflowOperationRecord} from './workflow-operation'
const props=defineProps<{provider:WorkflowOperationProvider;record:WorkflowOperationRecord;blocked:boolean;storage:Pick<Storage,'getItem'|'setItem'|'removeItem'>|null}>()
type Pending={id:string;kind:'apply'|'continue'|'rollback'|'validate';operationId:string;applyOperationId:string;input:Record<string,string>}
const preview=ref<WorkflowDeliveryPreview|null>(null),status=ref<WorkflowDeliveryStatus|null>(null),pending=ref<Pending|null>(null),applyId=ref(''),validationId=ref(''),validation=ref<WorkflowDeliveryValidation|null>(null),busy=ref(false),fault=ref(''),agreed=ref(false),corrupt=ref(false)
let alive=true,generation=0
watch(()=>[props.record.id,props.record.revision,props.record.goal.digest,props.record.plan?.digest,props.record.activeRunId],()=>{generation++},{flush:'sync'})
const current=(ticket:number)=>alive&&ticket===generation
const key=()=>`companion.workflow-delivery.v1.${props.record.id}`
function persist(){if(!props.storage)throw Error();const value=JSON.stringify({applyId:applyId.value,validationId:validationId.value,pending:pending.value});props.storage.setItem(key(),value);if(props.storage.getItem(key())!==value)throw Error()}
function clearPending(){const old=pending.value;pending.value=null;try{persist()}catch(error){pending.value=old;corrupt.value=true;throw error}}
function restore(){preview.value=null;status.value=null;pending.value=null;applyId.value='';validationId.value='';validation.value=null;fault.value='';corrupt.value=false;agreed.value=false;try{if(!props.storage)throw Error();const raw=props.storage.getItem(key());if(!raw)return;const v=JSON.parse(raw);if(typeof v.applyId!=='string'||(v.pending!==null&&(!v.pending||v.pending.id!==props.record.id||!['apply','continue','rollback','validate'].includes(v.pending.kind)||typeof v.pending.operationId!=='string'||typeof v.pending.applyOperationId!=='string'||!v.pending.input)))throw Error();applyId.value=v.applyId;validationId.value=typeof v.validationId==='string'?v.validationId:'';pending.value=v.pending}catch{corrupt.value=true;fault.value='交付请求记录不可读，操作已锁定。'}}
watch(()=>props.record.id,restore,{immediate:true})
watch(()=>[props.record.goal.digest,props.record.plan?.digest,props.record.activeRunId],()=>{preview.value=null;status.value=null;agreed.value=false})
async function readPreview(){if(busy.value||!props.provider.readDeliveryPreview)return;busy.value=true;preview.value=null;agreed.value=false;fault.value='';const record=props.record,ticket=generation;try{const p=await props.provider.readDeliveryPreview(record.id);if(!current(ticket))return;if(props.record.id!==record.id||p.workflowId!==record.id||p.goalDigest!==record.goal.digest||p.planDigest!==record.plan?.digest||p.runId!==record.activeRunId)throw Error();preview.value=p}catch{if(current(ticket))fault.value='交付预览读取失败或版本已变化，请重新核对。'}finally{if(alive)busy.value=false}}
async function readStatus(){if(busy.value||!applyId.value||!props.provider.readDeliveryStatus)return;busy.value=true;status.value=null;agreed.value=false;fault.value='';const id=props.record.id,op=applyId.value,ticket=generation;try{const result=await props.provider.readDeliveryStatus(id,op);if(!current(ticket))return;if(props.record.id!==id||result.workflowId!==id||result.operationId!==op)throw Error();status.value=result}catch{if(current(ticket))fault.value='交付状态读取失败，结果待核对。'}finally{if(alive)busy.value=false}}
async function submit(kind:Pending['kind']){if(busy.value||pending.value||corrupt.value||props.blocked||!agreed.value)return;const id=props.record.id,ticket=generation,operationId=crypto.randomUUID(),oldApplyId=applyId.value;if(kind==='apply'&&(!preview.value||applyId.value)||kind!=='apply'&&(!status.value?.observedDigest||!applyId.value))return;const input:Record<string,string>=kind==='apply'?{operationId,previewDigest:preview.value!.previewDigest,confirmation:'APPLY_REVIEWED_PATCH'}:{operationId,applyOperationId:applyId.value,observedDigest:status.value!.observedDigest!,confirmation:kind==='continue'?'CONTINUE_REVIEWED_PATCH':kind==='rollback'?'ROLLBACK_REVIEWED_PATCH':'RUN_FIXED_VALIDATION'};if(kind==='apply')applyId.value=operationId;if(kind==='validate'&&status.value?.state!=='applied')return;pending.value={id,kind,operationId,applyOperationId:applyId.value,input};try{persist()}catch{pending.value=null;applyId.value=oldApplyId;corrupt.value=true;fault.value='无法保存请求，未提交。';return}busy.value=true;agreed.value=false;try{if(kind==='validate'){const result=await props.provider.validateDelivery!(id,input as never);if(!current(ticket))return;if(result.workflowId!==id||result.operationId!==operationId||result.applyOperationId!==applyId.value)throw Error();validationId.value=operationId;validation.value=result}else{const result=kind==='apply'?await props.provider.applyDelivery!(id,input as never):kind==='continue'?await props.provider.continueDelivery!(id,input as never):await props.provider.rollbackDelivery!(id,input as never);if(!current(ticket))return;if(result.workflowId!==id||result.operationId!==applyId.value)throw Error();status.value=result}clearPending();preview.value=null;fault.value=kind==='validate'?'已读取本次验证结果；产品验收仍需单独核对。':'交付状态已读取；测试与产品验收仍需单独核对。'}catch(e){if(!current(ticket))return;if(e instanceof WorkflowCommandError&&e.outcome==='rejected'){const previousApplyId=applyId.value;if(kind==='apply')applyId.value='';try{clearPending()}catch{applyId.value=previousApplyId;corrupt.value=true}fault.value=e.code==='DELIVERY_ACTIVITY_UNPROVEN'?'执行活动尚无法确认，不能应用。':'请求已拒绝，请重新核对预览及状态。'}else fault.value='请求结果未知，保留原请求，先查询，不自动重发。'}finally{if(alive)busy.value=false}}
async function readValidation(){if(!validationId.value||!props.provider.readDeliveryValidation||busy.value)return;busy.value=true;const ticket=generation;try{const result=await props.provider.readDeliveryValidation(props.record.id,validationId.value);if(!current(ticket))return;if(result.workflowId!==props.record.id||result.operationId!==validationId.value||result.applyOperationId!==applyId.value)throw Error();validation.value=result}catch{if(current(ticket))fault.value='验证结果读取失败，待核对。'}finally{if(alive)busy.value=false}}
async function reconcile(){const p=pending.value;if(!p||busy.value)return;busy.value=true;const ticket=generation;try{const receipt=await props.provider.getOperation(p.operationId,p.id);if(!current(ticket))return;if(receipt.workflowId!==p.id||receipt.operationId!==p.operationId||receipt.state!=='settled'||!props.provider.readDeliveryStatus)throw Error();if(p.kind==='validate'){if(!props.provider.readDeliveryValidation)throw Error();const result=await props.provider.readDeliveryValidation(p.id,p.operationId);if(!current(ticket))return;if(result.workflowId!==p.id||result.operationId!==p.operationId||result.applyOperationId!==p.applyOperationId)throw Error();validationId.value=p.operationId;validation.value=result}else{const result=await props.provider.readDeliveryStatus(p.id,p.applyOperationId);if(!current(ticket))return;if(result.workflowId!==p.id||result.operationId!==p.applyOperationId)throw Error();status.value=result}clearPending();fault.value='已核对原请求及交付状态；未重发。'}catch{if(current(ticket))fault.value='结果仍待核对，保留原请求，不自动重发。'}finally{if(alive)busy.value=false}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{timer=setInterval(()=>{if(pending.value&&!busy.value)void reconcile()},15000)})
onBeforeUnmount(()=>{alive=false;generation++;if(timer)clearInterval(timer)})
</script>
<template><section aria-label="交付与应用"><h4>交付与应用</h4><p>任务目录验收、工程应用、实际测试和产品验收分别核对。</p><p v-if="blocked" role="status">当前目标状态待核对，交付写操作暂不可用。</p><p v-if="fault" role="status">{{ fault }}</p><p v-if="pending">原请求结果待核对。<button type="button" :disabled="busy" @click="reconcile">查询原请求</button></p><button type="button" :disabled="busy||!provider.readDeliveryPreview" @click="readPreview">读取交付预览</button><button v-if="applyId" type="button" :disabled="busy||!provider.readDeliveryStatus" @click="readStatus">读取应用状态</button><button v-if="validationId" type="button" :disabled="busy||!provider.readDeliveryValidation" @click="readValidation">读取验证结果</button><template v-if="preview"><p>目标工程：{{ preview.targetRoot }} · 观察时间 {{ preview.observedAt }}</p><p>执行活动未核验；预览不代表可以应用，后台将在应用时核对。</p><ul><li v-for="f in preview.files" :key="f.path">{{ f.path }} · 基线 {{ f.baselineDigest }}</li></ul><details><summary>查看补丁与技术摘要</summary><p>补丁 {{ preview.patchDigest }} · 预览 {{ preview.previewDigest }}</p><pre>{{ preview.patch }}</pre></details><label v-if="!applyId"><input v-model="agreed" type="checkbox">我已核对目标、文件范围与补丁，确认应用</label><button v-if="!applyId" type="button" :disabled="busy||!!pending||corrupt||blocked||!agreed||!provider.applyDelivery" @click="submit('apply')">应用已审阅补丁</button></template><template v-if="status"><p>当前应用状态：{{ status.state==='applied'?'已应用':status.state==='rolled-back'?'已回退':status.state==='not-applied'?'未应用':status.state==='partial'?'部分应用，待核对':'未知，待核对' }}；测试未核验。状态为 {{ status.observedAt }} 的观察，操作时后端会重新核对。</p><ul><li v-for="f in status.files" :key="f.path">{{ f.path }} · {{ f.state==='applied'?'已应用':f.state==='baseline'?'基线':'已变化，需核对' }}</li></ul><label><input v-model="agreed" type="checkbox">我已核对当前应用状态和文件</label><button v-if="status.state==='applied'" type="button" :disabled="busy||!!pending||corrupt||blocked||!agreed||!status.observedDigest||!provider.validateDelivery" @click="submit('validate')">确认运行固定验证</button><button v-if="status.state==='partial'" type="button" :disabled="busy||!!pending||corrupt||blocked||!agreed||!status.observedDigest||!provider.continueDelivery" @click="submit('continue')">确认继续应用</button><button v-if="['applied','partial'].includes(status.state)" type="button" :disabled="busy||!!pending||corrupt||blocked||!agreed||!status.observedDigest||!provider.rollbackDelivery" @click="submit('rollback')">确认回退应用</button></template><section v-if="validation" aria-label="固定验证结果"><p>固定验证：{{ validation.state==='passed'?'通过':validation.state==='failed'?'失败':'待核对' }}；不等于产品验收。</p><p>此结果绑定验证时的应用观察；当前文件状态请重新读取。</p><p v-if="!status||status.observedDigest!==validation.observedDigest">当前状态尚未核对或与验证时不同。</p><ul><li v-for="check in validation.checks" :key="check.id">{{ check.id }}：{{ check.state==='passed'?'通过':check.state==='failed'?'失败':'未运行' }}<details v-if="check.output"><summary>查看验证输出<span v-if="check.truncated">（已截断）</span></summary><pre>{{ check.output }}</pre></details></li></ul></section></section></template>
<style scoped>pre{white-space:pre-wrap;overflow:auto;max-height:320px}section{margin:12px 0;padding:12px;border:1px solid var(--el-border-color)}</style>
